  update public.dsr_item set rate = '84.85'::numeric, unit = 'sqm', description = 'Cleaning of under ground sump, Over Head R.C.C. Tank ( independent staging) including disposal of slit and rubbish, all as per direction of Engineer-in-Charge. The cleaning shall consist following operations:- (i)Tank shall be emptied of water by pumping & bottom shall be cleaned of silt and other deposits. (ii) Entire surface area of the sump shall then scrubbed thoroughly with wire brush etc. and pressure washed with water. (iii) Chlorination of RCC internal surface by liquid chlorine. (iv) The treated surface shall be dried using air jetting and all loose particles shall be removal from the surface. (v) Finally the surface shall be treated with ultraviolet radiation etc. as per direction of Engineer-in-Charge.' where id = '22039eb5-94e1-4bb9-b80b-df2cdef38796' and code = '14.78' and rate = 422.70 and unit = 'sqm';
